import { htmlLanguage } from "@codemirror/lang-html";
// generated by gen-tailwind-classes.cjs from Tailwind v3 (the version cdn.tailwindcss.com serves)
// esbuild inlines JSON imports, so this ends up inside editor.bundle.js
import data from "./tailwind-classes.json";

// built once, reused on every keystroke
const classOptions = data.classes.map((label) => ({ label, type: "class" }));
const variantOptions = data.variants.map((v) => ({
  label: `${v}:`,
  type: "keyword",
  boost: -1, // list real utilities above variants for the same prefix
}));
const options = [...classOptions, ...variantOptions];

// characters that can appear in a Tailwind class (including variants, "!" and negatives)
const WORD = /[\w:\-\/\[\]\.%#!]*/;
const VALID_FOR = /^[\w\-\/\[\]\.%#!]*$/;

function tailwindSource(context) {
  const line = context.state.doc.lineAt(context.pos);
  const before = line.text.slice(0, context.pos - line.from);
  if (!/class=["'][^"']*$/.test(before)) return null; // only inside class="..."

  const word = context.matchBefore(WORD);
  if (!word || (word.from === word.to && !context.explicit)) return null;

  // after "md:hover:" only complete the part after the last colon
  const colon = word.text.lastIndexOf(":");
  return {
    from: colon === -1 ? word.from : word.from + colon + 1,
    options,
    validFor: VALID_FOR,
  };
}

// adds to the HTML completions instead of replacing them
export const tailwindCompletion = htmlLanguage.data.of({
  autocomplete: tailwindSource,
});
